import React, { useState } from "react";
import { authenticateUser } from "../utils/storage";

const LoginForm = ({ onLogin }) => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    setError("");

    const user = authenticateUser(username, password);

    if (user) {
      // Don't include password in the user object
      const { password, ...userWithoutPassword } = user;
      onLogin(userWithoutPassword);
    } else {
      setError("Invalid username or password");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="login-form">
      {error && (
        <div
          className="error-message"
          style={{
            color: "#ef4444",
            backgroundColor: "#fee2e2",
            padding: "10px",
            borderRadius: "5px",
            marginBottom: "20px",
            textAlign: "center",
          }}
        >
          {error}
        </div>
      )}

      <div className="form-group">
        <label htmlFor="username">Username</label>
        <input
          type="text"
          id="username"
          className="form-control"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Enter your username"
          required
        />
      </div>

      <div className="form-group">
        <label htmlFor="password">Password</label>
        <input
          type="password"
          id="password"
          className="form-control"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Enter your password"
          required
        />
      </div>

      <button type="submit" className="btn" style={{ width: "100%" }}>
        Login
      </button>

      <div
        className="demo-credentials"
        style={{ marginTop: "20px", textAlign: "center" }}
      >
        <p style={{ color: "#666", fontSize: "14px", marginBottom: "5px" }}>
          <strong>Demo Credentials:</strong>
        </p>
        <p style={{ color: "#666", fontSize: "12px", marginBottom: "2px" }}>
          Admin: admin / admin123
        </p>
        <p style={{ color: "#666", fontSize: "12px" }}>
          Users: john / john123 | jane / jane123 | mike / mike123
        </p>
      </div>
    </form>
  );
};

export default LoginForm;
